package me.pikanote.companion;
import android.app.*;import android.content.*;import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;
final class PhoneVoiceChecks {
 static void check(boolean value,String message)throws Exception{if(!value)throw new Exception(message);}
 static String fixture(Store store,int pcm)throws Exception{String token=UUID.randomUUID().toString();try(OutputStream out=new FileOutputStream(store.safeFile(PhoneVoice.fileName(token)))){out.write(PhoneRecorder.header(pcm));out.write(new byte[pcm]);}return token;}
 static void data(Context context)throws Exception{Store store=new Store(context);String token=fixture(store,32000);PhoneVoice.enqueue(store,token,1000,"2026-10-28T14:00:00Z");Store reopened=new Store(context);check(PhoneVoice.job(reopened,token).getString("status").equals("queued"),"Recording queue not durable");PhoneVoice.processOne(reopened,(file,key)->"Это только заметка. Нужно сделать задачу завтра. Original English.");JSONObject job=PhoneVoice.job(reopened,token),snap=reopened.snapshot();check(job.getString("status").equals("ready")&&snap.getJSONArray("memories").length()==1,"Transcript not saved");check(snap.getJSONArray("tasks").length()==0&&snap.getJSONArray("events").length()==0,"Voice memory created actions");check(snap.getJSONArray("memories").getJSONObject(0).getBoolean("wav"),"Audio not visible before Pika sync");String local=job.getString("localId");check(reopened.voiceFile(local).length()==32044,"Local playback unavailable");check(reopened.state.getJSONArray("pending").getJSONObject(0).getJSONObject("body").getJSONObject("record").getString("date").equals("2026-10-28T16:00"),"Kyiv capture date malformed");PhoneVoice.finishTranscript(reopened,token,"Repeated result");check(reopened.snapshot().getJSONArray("memories").length()==1&&reopened.state.getJSONArray("pending").length()==1,"Transcription retry created duplicate memory");
 String failed=fixture(reopened,24000);PhoneVoice.enqueue(reopened,failed,750,"2026-10-28T14:01:00Z");PhoneVoice.processOne(reopened,(file,key)->{throw new IOException("Network interrupted");});check(PhoneVoice.job(reopened,failed).getString("status").equals("error")&&reopened.safeFile(PhoneVoice.fileName(failed)).isFile(),"Failed recognition lost WAV");PhoneVoice.job(reopened,failed).put("permanentError",true);PhoneVoice.retry(reopened,failed);check(!PhoneVoice.job(reopened,failed).optBoolean("permanentError"),"Explicit retry cannot clear key error");PhoneVoice.job(reopened,failed).put("status","transcribing");reopened.save();PhoneVoice.recover(reopened);check(PhoneVoice.job(reopened,failed).getString("status").equals("queued"),"Interrupted recognition not recovered");
 String orphan=fixture(reopened,32000);PhoneVoice.recover(reopened);check(PhoneVoice.job(reopened,orphan).getString("status").equals("queued"),"Crash between WAV save and intent lost capture");int before=PhoneVoice.jobs(reopened).length();PhoneVoice.recover(reopened);check(PhoneVoice.jobs(reopened).length()==before,"Orphan recovery duplicated capture");String shortToken=fixture(reopened,8000);boolean shortRejected=false;try{PhoneVoice.enqueue(reopened,shortToken,250,"2026-10-28T14:02:00Z");}catch(IOException expected){shortRejected=true;}check(shortRejected,"Sub-0.5-second recording accepted");reopened.safeFile(PhoneVoice.fileName(shortToken)).delete();
 Files.write(reopened.safeFile("index.csv").toPath(),"note,title\n".getBytes("UTF-8"));reopened.state.getJSONObject("files").put("index.csv",PhoneVoice.hash(reopened.safeFile("index.csv")));reopened.save();ByteArrayOutputStream bytes=new ByteArrayOutputStream();PhoneBackup.write(reopened,bytes);PhoneBackup.restore(reopened,new ByteArrayInputStream(bytes.toByteArray()));check(reopened.safeFile(PhoneVoice.fileName(token)).isFile()&&PhoneVoice.jobs(reopened).length()==before,"Backup omitted unsynced audio queue");reopened.state.getJSONObject("ids").put(local,"m42");check(reopened.voiceFile("m42").isFile(),"Resolved ID lost playback");reopened.queueMutation(new JSONObject().put("kind","memories").put("action","delete").put("id",local).put("clientRequest","forget-voice-test"));check(reopened.voiceFile("m42")==null&&!reopened.safeFile(PhoneVoice.fileName(token)).exists(),"Forget retained accessible voice audio");}
 static void ui(Instrumentation i)throws Exception{Context real=i.getTargetContext();File dir=new File(real.getFilesDir(),"voice-ui-check");Context sandbox=new ContextWrapper(real){public File getFilesDir(){dir.mkdirs();return dir;}};Store store=new Store(sandbox);store.state.put("appLock",false);store.save();java.lang.reflect.Field singleton=Store.class.getDeclaredField("singleton");singleton.setAccessible(true);singleton.set(null,store);MainActivity.instrumentPreview=true;MainActivity activity=null;try{activity=(MainActivity)i.startActivitySync(new Intent(real,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));UiRefreshChecks.await(i,activity,"typeof render==='function'&&!!db.libraryVersion");UiRefreshChecks.eval(i,activity,"tab='memories';render();document.querySelector('[data-new=memories]').click()");UiRefreshChecks.await(i,activity,"document.getElementById('phone-voice-dialog').open");check("2".equals(UiRefreshChecks.eval(i,activity,"document.querySelectorAll('#phone-voice-dialog .voice-method').length")),"Two memory methods missing");UiRefreshChecks.eval(i,activity,"document.getElementById('phone-write-memory').click()");UiRefreshChecks.await(i,activity,"document.getElementById('editor').open");UiRefreshChecks.eval(i,activity,"closeEdit();document.querySelector('[data-new=memories]').click();window.starts=[];window.stops=[];window.pikaStartVoice=t=>starts.push(t);window.pikaStopVoice=(t,c)=>stops.push(c);window.testMic=document.getElementById('phone-record-memory');testMic.setPointerCapture=()=>{};testMic.dispatchEvent(new PointerEvent('pointerdown',{button:0,pointerId:1,clientX:200,bubbles:true}));pikaVoiceEvent({token:starts[0],state:'recording',durationMs:2000});testMic.dispatchEvent(new PointerEvent('pointerup',{button:0,pointerId:1,clientX:200,bubbles:true}))");check("true".equals(UiRefreshChecks.eval(i,activity,"stops.length===1&&stops[0]===false")),"Release did not save capture");UiRefreshChecks.eval(i,activity,"testMic.dispatchEvent(new PointerEvent('pointerdown',{button:0,pointerId:2,clientX:200,bubbles:true}));testMic.dispatchEvent(new PointerEvent('pointermove',{pointerId:2,clientX:100,bubbles:true}));testMic.dispatchEvent(new PointerEvent('pointerup',{pointerId:2,clientX:100,bubbles:true}))");check("true".equals(UiRefreshChecks.eval(i,activity,"stops.length===2&&stops[0]===false&&stops[1]===true")),"Slide left did not cancel");UiRefreshChecks.eval(i,activity,"pikaHandleBack()");UiRefreshChecks.await(i,activity,"!document.getElementById('phone-voice-dialog').open");}finally{if(activity!=null){MainActivity close=activity;i.runOnMainSync(close::finish);}singleton.set(null,null);MainActivity.instrumentPreview=false;PhoneBackup.remove(dir);}}
}
